// C++ test fixture plugin for polyplug integration tests.
//
// Hand-written (not generated by polyplugc) to mirror the Rust `test_plugin`
// fixture exactly. It implements the "test.add" contract: add(a, b) -> a + b.
//
// The dispatch entry stored in `functions[0]` uses the polyplug native calling
// convention `extern "C" AbiError(const void* args, void* out)` — the same
// 2-argument shape the Rust fixture exports and that the tests transmute to.
//
// The ABI structs below are declared locally with C-compatible layout so the
// fixture stays self-contained and does not depend on generated bindings.

#include <cstddef>
#include <cstdint>

namespace {

// ─── ABI types (C-layout, mirrors polyplug_abi) ──────────────────────────────

struct StringView {
    const uint8_t* ptr;
    size_t len;
};

struct Version {
    uint32_t major;
    uint32_t minor;
    uint32_t patch;
};

enum class AbiErrorCode : uint32_t {
    Ok = 0,
    Generic = 1,
};

struct AbiError {
    AbiErrorCode code;
    StringView message;
};

enum class DispatchType : uint32_t {
    Native = 0,
    VirtualMachine = 1,
};

struct GuestContractInstance {
    void* data;
    uint64_t contract_id;
};

struct NativeDispatch {
    uint32_t function_count;
    void* const* functions;
};

struct VmDispatch {
    void* call;
    void* loader_data;
};

union DispatchMechanisms {
    NativeDispatch native;
    VmDispatch vm;
};

struct PluginDescriptor {
    StringView name;
    StringView contract_name;
    Version version;
};

struct BundleInitContext {
    uint64_t bundle_id;
    StringView bundle_path;
};

using create_instance_fn = GuestContractInstance (*)(const void* host, const void* args);
using destroy_instance_fn = void (*)(const void* host, GuestContractInstance instance);

struct GuestContractInterface {
    uint64_t contract_id;
    Version contract_version;
    DispatchType dispatch_type;
    create_instance_fn create_instance;
    destroy_instance_fn destroy_instance;
    DispatchMechanisms dispatch;
};

// HostInterface is opaque to this fixture except for `register_contract`, which
// is the first function pointer following the leading `runtime` pointer.
using register_contract_fn = AbiError (*)(const void* host,
                                          const PluginDescriptor* descriptor,
                                          const GuestContractInterface* interface);

struct HostInterface {
    void* runtime;
    register_contract_fn register_contract;
    // Remaining function pointers are unused by this fixture.
};

// ─── test.add contract ───────────────────────────────────────────────────────

// FNV-1a 64-bit hash, evaluated at compile time, matching polyplug_utils.
constexpr uint64_t fnv1a_64(const char* data) {
    uint64_t hash = 0xcbf29ce484222325ULL;
    while (*data != '\0') {
        hash ^= static_cast<uint64_t>(static_cast<unsigned char>(*data));
        hash *= 0x00000100000001b3ULL;
        ++data;
    }
    return hash;
}

// Canonical guest contract ID for "test.add@1" — must match the Rust
// test_plugin fixture (fnv1a_64("guest_contract:test.add@1") = 0x40244DF59FCBECB6).
constexpr uint64_t kTestAddContractId = fnv1a_64("guest_contract:test.add@1");

struct AddArgs {
    uint32_t a;
    uint32_t b;
};

AbiError cpp_test_add(const void* args, void* out) noexcept {
    const AddArgs* in = static_cast<const AddArgs*>(args);
    *static_cast<uint32_t*>(out) = in->a + in->b;
    return AbiError{AbiErrorCode::Ok, StringView{nullptr, 0}};
}

GuestContractInstance create_instance_stub(const void*, const void*) noexcept {
    return GuestContractInstance{nullptr, 0};
}

void destroy_instance_stub(const void*, GuestContractInstance) noexcept {}

void* const kTestAddFns[] = {
    reinterpret_cast<void*>(&cpp_test_add),
};

GuestContractInterface kTestAddInterface = {
    kTestAddContractId,
    Version{1, 0, 0},
    DispatchType::Native,
    create_instance_stub,
    destroy_instance_stub,
    DispatchMechanisms{.native = NativeDispatch{1, kTestAddFns}},
};

const PluginDescriptor kTestAddDescriptor = {
    StringView{reinterpret_cast<const uint8_t*>("test_adder_cpp"), 14},
    StringView{reinterpret_cast<const uint8_t*>("test.add"), 8},
    Version{1, 0, 0},
};

}  // namespace

// ─── ABI exports ──────────────────────────────────────────────────────────────

extern "C" uint32_t polyplug_abi_version() {
    return 1U;
}

extern "C" AbiError polyplug_init(const HostInterface* host, const BundleInitContext* ctx) {
    if (host == nullptr || ctx == nullptr) {
        return AbiError{AbiErrorCode::Generic, StringView{nullptr, 0}};
    }
    return host->register_contract(host, &kTestAddDescriptor, &kTestAddInterface);
}
